// Keep only useful account evidence and propagate the configuration.
let config = {};
try { config = $('Set Template Fields').first().json || {}; } catch (error) {}
const results = [];
function header(item, name) {
  const headers = item.json?.payload?.headers || item.json?.headers || [];
  const found = Array.isArray(headers) ? headers.find(h => String(h.name || '').toLowerCase() === name.toLowerCase()) : null;
  return String(found?.value || item.json?.[name.toLowerCase()] || item.json?.[name] || '');
}
function clean(value) {
  return String(value || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}
for (const item of $input.all()) {
  const j = item.json || {};
  const messageId = String(j.id || j.messageId || '').trim();
  const from = header(item, 'From') || String(j.from || '');
  const subject = header(item, 'Subject') || String(j.subject || '');
  const body = clean(j.textPlain || j.text || j.snippet || j.body?.data || '');
  if (!messageId || body.length < 24) continue;
  if (/mailer-daemon|postmaster|no-?reply.*(delivery|bounce)/i.test(from)) continue;
  results.push({ json: {
    ...config,
    messageId,
    threadId: String(j.threadId || ''),
    receivedAt: String(j.internalDate || j.date || new Date().toISOString()),
    sourceFrom: from,
    sourceSubject: subject,
    messageBody: body.slice(0, 12000),
    sourceLink: 'https://mail.google.com/mail/u/0/#all/' + encodeURIComponent(messageId),
  }});
}
return results;

// Build a model-neutral request; no API key is stored in the workflow.
const instruction = String.raw`You create a privacy inventory from one email that may indicate an online account. Return ONLY valid JSON with exactly this schema:
{
  "message_id":"string copied exactly",
  "is_account_signal":true,
  "service_name":"brand or service name",
  "service_domain":"registrable domain only, for example example.com, or empty string",
  "account_category":"One of Finance, Health, Government, Identity, Shopping, Social, Media, Productivity, Travel, Utilities, Education, Other",
  "account_evidence":"short factual description of why this email indicates an account",
  "billing_signal":"none|possible|confirmed",
  "sensitive_signal":true,
  "confidence":0.0,
  "reason":"short explanation"
}
Rules: An account signal can be a welcome, verification, login, password reset, receipt, subscription, or policy-change email. Ignore marketing-only messages that do not imply an account. Never extract passwords, full card numbers, government IDs, health details, message attachments, or personal secrets. Do not invent a service domain.`;
return $input.all().map(item => {
  const j = item.json || {};
  return { json: {
    ...j,
    aiRequestBody: {
      model: j.aiModel,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [{ role: 'user', content: instruction + '\n\nMessage ID: ' + j.messageId + '\nFrom: ' + j.sourceFrom + '\nSubject: ' + j.sourceSubject + '\nReceived: ' + j.receivedAt + '\n\nEmail body:\n' + j.messageBody }],
    },
  }};
});

// Restore context after HTTP Request with the unique Gmail Message ID.
const responses = $input.all();
let sources = [];
try { sources = $('Build Account Inventory AI Request').all(); } catch (error) {}
const allowedCategories = new Set(['Finance', 'Health', 'Government', 'Identity', 'Shopping', 'Social', 'Media', 'Productivity', 'Travel', 'Utilities', 'Education', 'Other']);
const results = [];
function normaliseDomain(value) {
  return String(value || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].replace(/[^a-z0-9.-]/g, '');
}
for (const response of responses) {
  let extraction = {};
  let parseError = '';
  try {
    const raw = response.json?.choices?.[0]?.message?.content || response.json?.output || response.json;
    extraction = typeof raw === 'string' ? JSON.parse(raw.replace(/^\u0060\u0060\u0060json\s*/i, '').replace(/\u0060\u0060\u0060$/i, '').trim()) : raw;
  } catch (error) { parseError = String(error.message || error); }
  const messageId = String(extraction?.message_id || '');
  const source = sources.find(item => String(item.json?.messageId || '') === messageId);
  if (!source) continue;
  const serviceName = String(extraction?.service_name || '').trim();
  const serviceDomain = normaliseDomain(extraction?.service_domain);
  const confidence = Number(extraction?.confidence);
  const category = allowedCategories.has(String(extraction?.account_category || '')) ? String(extraction.account_category) : 'Other';
  const sensitiveByCategory = String(source.json.sensitiveCategories || '').split(',').map(v => v.trim()).includes(category);
  const isAccountSignal = extraction?.is_account_signal === true;
  const status = !isAccountSignal ? 'Ignored' : (parseError || !serviceName || !Number.isFinite(confidence) || confidence < Number(source.json.minimumConfidence || 0.82) ? 'Needs review' : 'Open');
  const keyPart = serviceDomain || serviceName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  const senderDomain = String(source.json.sourceFrom || '').toLowerCase().match(/@([a-z0-9.-]+)/)?.[1] || 'unknown-sender';
  const accountKey = keyPart ? keyPart + '::' + senderDomain : source.json.messageId;
  const billing = ['confirmed', 'possible'].includes(String(extraction?.billing_signal || '').toLowerCase()) ? String(extraction.billing_signal).toLowerCase() : 'none';
  const riskScore = Math.min(100, Math.round((sensitiveByCategory || extraction?.sensitive_signal ? 35 : 0) + (billing === 'confirmed' ? 25 : billing === 'possible' ? 12 : 0) + (category === 'Identity' || category === 'Government' ? 20 : 0) + (status === 'Needs review' ? 15 : 0) + (confidence < 0.9 ? 8 : 0)));
  results.push({ json: {
    ...source.json,
    accountKey,
    isAccountSignal,
    serviceName,
    serviceDomain,
    accountCategory: category,
    accountEvidence: String(extraction?.account_evidence || '').trim(),
    billingSignal: billing,
    sensitiveSignal: Boolean(sensitiveByCategory || extraction?.sensitive_signal),
    confidence: Number.isFinite(confidence) ? confidence : 0,
    riskScore,
    status,
    reviewReason: String(extraction?.reason || parseError || '').trim(),
  }});
}
return results;

// Create a privacy-minimised, source-backed row for the Account Register.
return $input.all().map(item => {
  const j = item.json || {};
  const now = new Date().toLocaleString('en-CA', { timeZone: j.timezone || 'America/Toronto' });
  return { json: {
    'Account Key': j.accountKey || j.messageId || '',
    'Status': j.status || 'Needs review',
    'Service Name': j.serviceName || '',
    'Service Domain': j.serviceDomain || '',
    'Category': j.accountCategory || 'Other',
    'Sensitive Signal': j.sensitiveSignal ? 'Yes' : 'No',
    'Billing Signal': j.billingSignal || 'none',
    'Risk Score': j.riskScore ?? 0,
    'Confidence': j.confidence ?? 0,
    'Account Evidence': j.accountEvidence || '',
    'First Observed At': j.receivedAt || now,
    'Last Observed At': j.receivedAt || now,
    'Source From': j.sourceFrom || '',
    'Source Subject': j.sourceSubject || '',
    'Source Message ID': j.messageId || '',
    'Source Thread ID': j.threadId || '',
    'Source Link': j.sourceLink || '',
    'Desired Action': 'Review',
    'Data Rights Draft': '',
    'Review Reason': j.reviewReason || '',
    'Last Digest At': '',
  }};
});

// Merge fresh evidence with existing rows without overwriting a person's decisions.
let proposed = [];
try { proposed = $('Prepare Account Register Row').all(); } catch (error) {}
const existingByKey = new Map($input.all().map(item => [String(item.json?.['Account Key'] || ''), item.json || {}]));
const results = [];
for (const item of proposed) {
  const row = item.json || {};
  const existing = existingByKey.get(String(row['Account Key'] || '')) || {};
  const existingStatus = String(existing.Status || '').trim();
  const keepClosed = existingStatus === 'Closed';
  results.push({ json: {
    ...row,
    'Status': keepClosed ? 'Closed' : (row.Status || existingStatus || 'Needs review'),
    'First Observed At': existing['First Observed At'] || row['First Observed At'],
    'Desired Action': existing['Desired Action'] || row['Desired Action'] || 'Review',
    'Data Rights Draft': existing['Data Rights Draft'] || row['Data Rights Draft'] || '',
    'Last Digest At': existing['Last Digest At'] || row['Last Digest At'] || '',
  }});
}
return results;

// Google Sheets replaces the input, so restore it using the Account Key.
let prepared = [];
try { prepared = $('Prepare Account Register Row').all(); } catch (error) {}
const results = [];
for (const item of $input.all()) {
  const key = String(item.json?.['Account Key'] || '');
  const source = prepared.find(entry => String(entry.json?.['Account Key'] || '') === key);
  if (source) results.push({ json: { ...source.json } });
}
return results;

