// Prioritise human decisions; the workflow never submits deletion or export requests.
const rows = $input.all().map(item => item.json || {});
let config = {};
try { config = $('Set Template Fields').first().json || {}; } catch (error) {}
const priority = [];
for (const row of rows) {
  const status = String(row.Status || '').trim();
  if (status === 'Ignored' || status === 'Closed') continue;
  const action = String(row['Desired Action'] || 'Review').trim();
  const risk = Number(row['Risk Score'] || 0);
  const confidence = Number(row.Confidence || 0);
  const needsAction = ['Review', 'Export data', 'Delete account'].includes(action) || status === 'Needs review';
  if (!needsAction) continue;
  const draft = action === 'Delete account'
    ? 'Subject: Request to delete my account and personal data\n\nHello ' + (row['Service Name'] || 'privacy team') + ',\n\nPlease delete my account and personal data associated with this email address. Please confirm completion and tell me what data you must retain and why.\n\nThank you.'
    : action === 'Export data'
      ? 'Subject: Request for a copy of my personal data\n\nHello ' + (row['Service Name'] || 'privacy team') + ',\n\nPlease provide a copy of the personal data associated with this email address, including a description of the categories and sources of that data.\n\nThank you.'
      : '';
  priority.push({ row, action, risk, confidence, draft });
}
priority.sort((a, b) => (b.risk + (b.action !== 'Review' ? 30 : 0)) - (a.risk + (a.action !== 'Review' ? 30 : 0)));
const top = priority.slice(0, 12);
if (!top.length) return [];
const lines = top.map((entry, index) => {
  const r = entry.row;
  const actionLine = entry.action === 'Review' ? 'Review the source evidence.' : 'Copy this draft after checking the service privacy process:\n' + entry.draft;
  return (index + 1) + '. ' + (r['Service Name'] || 'Unknown service') + ' | Risk ' + entry.risk + '/100 | ' + (r.Category || 'Other') + ' | Action: ' + entry.action + '\nEvidence: ' + (r['Account Evidence'] || r['Source Subject'] || '') + '\nSource: ' + (r['Source Link'] || '') + '\n' + actionLine;
}).join('\n\n');
return [{ json: {
  ...config,
  reviewCount: priority.length,
  digestBody: 'Digital Closet Audit found ' + priority.length + ' account record(s) needing a decision.\n\n' + lines + '\n\nThis digest is a privacy planning aid, not legal advice. The workflow never sends requests or closes accounts for you.',
}}];
